use verus::prelude::*;

#[verifier::requires(
    // We must ensure that n + m - 1 really does fit into an i8
    (n as i64) + (m as i64) - 1 >= i8::MIN as i64
    &&
    (n as i64) + (m as i64) - 1 <= i8::MAX as i64
)]
#[verifier::ensures(
    // Let (first, second) = the returned pair.
    //   second == min(n,m)
    //   first  == max(n,m) - 1
    //   first + second == (n + m - 1)
    |(first, second): (i8, i8)| 
        second == n.min(m)
        &&
        first  == n.max(m) - 1
        &&
        first + second == n + m - 1
)]
fn solve(n: i8, m: i8) -> (i8, i8) {
    // the smaller of n and m
    let second = n.min(m);
    // help the verifier see that this matches our postcondition
    assert!(second == n.min(m));

    // the "other" piece
    let first = n + m - 1 - second;
    // a couple more checks for the verifier
    assert!(first + second == n + m - 1);
    assert!(first == n.max(m) - 1);

    (first, second)
}

